	if err != nil {
		return err
	}
	if !transitioned {
		return nil
	}
	notice, err := createNotice(ctx, db, task.ProjectID, task.ID, "task_lost", task.Title+" lost its Worker", now)
	if err != nil {
		return err
	}
	*notices = append(*notices, notice)
	return nil
}

